const portfolio = [
  { symbol: 'BBAI', sector: 'IA défense', status: 'portfolio' },
  { symbol: 'HIMS', sector: 'Téléhealth', status: 'portfolio' },
  { symbol: 'HYLN', sector: 'Camions électriques', status: 'portfolio' },
  { symbol: 'MMED', sector: 'Psychédéliques thérapeutiques', status: 'portfolio' },
  { symbol: 'PRCH', sector: 'Assurance tech', status: 'portfolio' },
  { symbol: 'RGTI', sector: 'Informatique quantique', status: 'portfolio' },
  { symbol: 'VUZI', sector: 'Smart glasses / AR', status: 'portfolio' },
  { symbol: 'XYL', sector: "Gestion de l'eau", status: 'portfolio' }
];
const watchlist = [
  { symbol: 'SMR', sector: 'Nucléaire SMR', status: 'watchlist' },
  { symbol: 'ALTD', sector: 'Drones FR', status: 'watchlist' },
  { symbol: 'OKLO', sector: 'Nucléaire SMR', status: 'watchlist' },
  { symbol: 'BLNK', sector: 'Recharge VE', status: 'watchlist' },
  { symbol: 'GRO', sector: 'Santé mentale', status: 'watchlist' },
  { symbol: 'STIM', sector: 'Neuromodulation', status: 'watchlist' },
  { symbol: 'PLX', sector: 'Diagnostics moléculaires', status: 'watchlist' }
];
return [...portfolio, ...watchlist].map(t => ({ json: t }));

const { symbol, sector, status } = $input.item.json;
await new Promise(r => setTimeout(r, 2000));
const date = new Date().toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' });

const skipRule = `RÈGLE ABSOLUE N°1 : Si tu ne trouves aucune actualité datant de moins de 7 jours sur ${symbol}, réponds UNIQUEMENT le mot : SKIP\nRÈGLE ABSOLUE N°2 : Ne répète pas une actualité déjà couverte dans un briefing précédent. Si tu n'as rien de nouveau à dire, réponds UNIQUEMENT le mot : SKIP\nSi l'une de ces deux règles s'applique, ta réponse doit être exclusivement : SKIP (rien d'autre).`;

let prompt;
if (status === 'portfolio') {
  prompt = `Tu es un analyste financier expert. Tu analyses l'action ${symbol} (${sector}) pour un investisseur qui la DÉTIENT DÉJÀ en portefeuille (aujourd'hui ${date}).

${skipRule}

Si des actualités récentes existent, utilise web_search pour les trouver, puis génère le briefing suivant.

Focus obligatoire : risques à surveiller, signaux de sortie, news impactant directement la position.

Format OBLIGATOIRE (markdown) :

## 💼 ${symbol} — ${sector} | Briefing du ${date}

### 📰 Actualités récentes (< 7 jours)
- [3 à 5 faits marquants datés]

### ⚠️ Impact sur ta position
- Risques identifiés : ...
- Points positifs : ...

### 🎯 Signal du jour
**[CONSERVER / RENFORCER / ALLÉGER / VENDRE]** — Confiance : [Faible / Moyenne / Forte]

### 📝 Verdict
[2-3 phrases concrètes pour un investisseur qui détient déjà ce titre]`;
} else {
  prompt = `Tu es un analyste financier expert. Tu analyses l'action ${symbol} (${sector}) pour un investisseur qui la SURVEILLE sans l'avoir encore achetée (aujourd'hui ${date}).

${skipRule}

Si des actualités récentes existent, utilise web_search pour les trouver, puis génère le briefing suivant.

Focus obligatoire : opportunité d'entrée, catalyseurs à venir, niveau de prix intéressant.

Format OBLIGATOIRE (markdown) :

## 👀 ${symbol} — ${sector} | Briefing du ${date}

### 📰 Actualités récentes (< 7 jours)
- [3 à 5 faits marquants datés]

### 💡 Opportunité d'entrée
- Niveau de prix intéressant : ...
- Catalyseurs à venir : ...

### 🎯 Signal du jour
**[ACHETER MAINTENANT / ATTENDRE / IGNORER]** — Confiance : [Faible / Moyenne / Forte]

### 📝 Verdict
[2-3 phrases concrètes pour un investisseur qui envisage d'acheter ce titre]`;
}

const body = {
  model: 'claude-sonnet-4-5',
  max_tokens: 1024,
  tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 3 }],
  messages: [{ role: 'user', content: prompt }]
};

return [{ json: { symbol, sector, status, body } }];

const response = $input.item.json;
const { symbol, sector, status } = $('Préparer requête Claude').item.json;

let briefing = '';
if (response.content && Array.isArray(response.content)) {
  for (const block of response.content) {
    if (block.type === 'text') briefing += block.text;
  }
}

const skip = !briefing || briefing.trim().toUpperCase() === 'SKIP';
return [{ json: { symbol, sector, status, briefing: briefing.trim(), skip } }];

const all = $input.all();
const totalTickers = 15;
const active = all.filter(i => !i.json.skip);
const portfolio = active.filter(i => i.json.status === 'portfolio');
const watchlist = active.filter(i => i.json.status === 'watchlist');
const date = new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

if (active.length === 0) {
  return [{ json: {
    htmlBody: '<html><body style="font-family:Arial,sans-serif;padding:24px"><p>Aucune actualité récente aujourd\'hui.</p></body></html>',
    subject: `📈 Veille Boursière — ${new Date().toLocaleDateString('fr-FR')} — Aucune news`
  }}];
}

const activeSymbols = active.map(i => i.json.symbol).join(', ');

function esc(s) { return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function mdToHtml(md) {
  return md
    .replace(/^## (.+)$/gm, '<h2 style="color:#1a1a2e;font-size:18px;margin:20px 0 8px">$1</h2>')
    .replace(/^### (.+)$/gm, '<h3 style="color:#444;font-size:15px;margin:14px 0 6px">$1</h3>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/^- (.+)$/gm, '<li>$1</li>')
    .replace(/(<li>.*<\/li>\n?)+/g, s => '<ul style="margin:4px 0 8px 20px">' + s + '</ul>')
    .replace(/\n{2,}/g, '</p><p>')
    .replace(/\n/g, '<br>');
}

function renderSection(title, items) {
  if (!items.length) return '';
  let html = `<h2 style="color:#1a1a2e;font-size:20px;margin:32px 0 12px;padding-bottom:6px;border-bottom:3px solid #e94560">${title} <span style="font-size:13px;color:#888;font-weight:normal">(${items.length} action${items.length>1?'s':''})</span></h2>`;
  for (const item of items) {
    html += `<div style="margin:16px 0;padding:16px 20px;background:#f9f9f9;border-left:4px solid #e94560;border-radius:3px">${mdToHtml(item.json.briefing)}</div>`;
  }
  return html;
}

const body = `<html><body style="font-family:Arial,sans-serif;max-width:820px;margin:auto;padding:24px;color:#222">
<h1 style="color:#1a1a2e;font-size:24px;border-bottom:3px solid #e94560;padding-bottom:10px">📈 Veille Boursière — ${date}</h1>
<div style="background:#e8f4fd;border-left:4px solid #2196F3;padding:12px 16px;margin:16px 0;font-size:14px">
  📊 <strong>${active.length} action${active.length>1?'s':''} sur ${totalTickers} ont des actualités aujourd'hui :</strong> ${activeSymbols}
</div>
${renderSection('📊 MON PORTEFEUILLE', portfolio)}
${renderSection('👀 MA WATCHLIST', watchlist)}
<p style="color:#bbb;font-size:11px;margin-top:32px;border-top:1px solid #eee;padding-top:10px">Généré par votre agent de veille boursière n8n + Claude</p>
</body></html>`;

return [{ json: {
  htmlBody: body,
  subject: `📈 Veille Boursière — ${new Date().toLocaleDateString('fr-FR')} — ${active.length}/${totalTickers} news`
}}];

const all = $input.all();
const active = all.filter(i => !i.json.skip);
return active.map(i => ({ json: { symbol: i.json.symbol, briefing: i.json.briefing } }));

const { symbol, briefing } = $input.item.json;
const MAX = 4000;

if (briefing.length <= MAX) {
  return [{ json: { chunk: briefing } }];
}

const paragraphs = briefing.split(/\n\n+/);
const chunks = [];
let current = '';

for (const para of paragraphs) {
  const candidate = current ? current + '\n\n' + para : para;
  if (candidate.length > MAX) {
    if (current) chunks.push(current);
    if (para.length > MAX) {
      const lines = para.split('\n');
      let sub = '';
      for (const line of lines) {
        const c = sub ? sub + '\n' + line : line;
        if (c.length > MAX) { if (sub) chunks.push(sub); sub = line; }
        else sub = c;
      }
      current = sub;
    } else {
      current = para;
    }
  } else {
    current = candidate;
  }
}
if (current) chunks.push(current);

return chunks.map((chunk, i) => ({
  json: { chunk: chunks.length > 1 ? `_(${i+1}/${chunks.length})_\n\n${chunk}` : chunk }
}));
